// The testing vertex spheres became a bit more.
// This was a lesson on dot(a,b)/dot(b,b) usefulness.

#define PI 3.141592653589793
#define TAU (2.*PI)

float dot2(vec3 v) { return dot(v,v); }

float vertsize = .2;
// Comment out this for just the polygons:
#define VERTEXSZ vertsize

// Extension of IQ udTriangle https://www.shadertoy.com/view/4sXXRN https://iquilezles.org/articles/triangledistance/
// Create exact regular polygon from 2 sides and count
float sdPolygon(vec3 p,vec3 a,vec3 b,vec3 c,float cntf) {
    int cnt = int(floor(cntf));
    vec3 nor = cross( c-b, b-a ); // normal for plane
    vec3 aa = a; // save a
    float numinside =  // < cnt means p not inside every polygon edge
        sign(dot(cross(b-a,nor),p-a)) +
        sign(dot(cross(c-b,nor),p-b));
    float outsidedistsq = min(
        dot2( (b-a) * clamp( dot((b-a),p-a)/dot2((b-a)), 0., 1. ) - (p-a) ),
        dot2( (c-b) * clamp( dot((c-b),p-b)/dot2((c-b)), 0., 1. ) - (p-b) ) );
#ifdef VERTEXSZ
float dist = 1e9;
dist = min( dist, length(p-a+vec3((1.-fract(cntf))*8.))); // traveling vertex
dist = min( dist, length(p-a) );
dist = min( dist, length(p-b) );
#endif
    for ( int cc = 3; cc < cnt; ++cc ) {
        vec3 t = a + (c-b)*( 1. + 2.*dot(c-b,b-a)/dot2(c-b) ); // derive next vertex from previous 3
        a = b; b = c; c = t; // work with next 3 vertices
#ifdef VERTEXSZ
dist = min( dist, length(p-b) );
#endif
        numinside += sign(dot(cross(c-b,nor),p-b));
        outsidedistsq = min( outsidedistsq, dot2( (c-b) * clamp( dot((c-b),p-b)/dot2((c-b)), 0., 1. ) - (p-b) ) );
    }
    numinside += sign(dot(cross(aa-c,nor),p-c));
    outsidedistsq = min( outsidedistsq, dot2( (aa-c) * clamp( dot((aa-c),p-c)/dot2((aa-c)), 0., 1. ) - (p-c) ) );
    float res = sqrt( numinside < float(cnt) ? outsidedistsq : dot(nor,p-aa)*dot(nor,p-aa)/dot2(nor) );
#ifdef VERTEXSZ
dist = min( dist, length(p-c) ) - VERTEXSZ;
res = min( dist, res );    
#endif
    return res;
}

// From edge size and number of sides, create a polygon
float sdPolygon2(vec3 p,float edge,float cntf) {
    float cnt = floor(cntf);
    float ang = PI-(cnt-2.)*PI/cnt;
    vec3 a=vec3(0);
    vec3 b=vec3(edge,0,0);
    vec3 c=vec3(edge*cos(ang),edge*sin(ang),0) + b;
    return sdPolygon( p, a, b, c, cntf );
}

// **************************************************************

#define ROT2(ANG) mat2(cos(ANG),sin(ANG),-sin(ANG),cos(ANG))

#define tanh1(X) (tanh(X)*.5+.5)

#define tri(X) (abs(fract(X)*4.-2.)-1.)
#define tri1(X) abs(fract(X)*2.-1.)
#define triab(X,A,B) (tri1(X)*((B)-(A))+(A))

#define sin1(X) (.5+.5*sin(X))
#define sinab(X,A,B) (sin1(X)*(B-A)+A)

#define cos1(X) (.5-.5*cos(X))
#define cosab(X,A,B) (cos1(X)*(B-A)+A)

vec3 Spin(float tim,vec3 p) {
   tim += iTime;
   p.xz *= ROT2(tim*.5);
   p.yz *= ROT2(tim*.3);
   p.yx *= ROT2(tim*.1);
   return p;
}

// **************************************************************

#define T(SDF) if ( (tmp = SDF) < hit.x ) hit = vec2(tmp,clr); clr += 1.;
#define C(SDF,CLR) if ( (tmp = SDF) < hit.x ) hit = vec2(tmp,CLR);

float thick = .1;

vec2 Dist(vec3 pt) {
    vec2 hit = vec2(100000,0);
    float tmp, clr = 0.;
    for ( float k=0.; k < 5.; ++k ) {
        float sds = triab( iTime*.05+k*.1,  sqrt(2.1) , sqrt(12.3) ); // number of sides
        T(sdPolygon2( Spin(k*4.,pt-vec3(0,0,9))-vec3(1,-1.5,2), 4./sds, sds*sds ) - thick);
    }
    C( 20.-pt.z, 90. )
    return hit;
}

vec4 March(vec3 beg,vec3 dir) {
    float dist = 0.;
    vec3 pos;
    #define LIMIT 410
    for ( int stps = 0; stps <= LIMIT; ++stps ) {
        pos = beg + dir * dist;
        vec2 obj = Dist( pos );
        dist += obj.x;
        if ( obj.x < .001 || stps == LIMIT ) return vec4( pos, obj.y );
    }
    return vec4( pos, 91. );
}

vec3 Normal(vec3 pt) {
    vec2 delta = vec2(.001,0);
    vec3 norm = Dist(pt).x - vec3(
        Dist(pt-delta.xyy).x, 
        Dist(pt-delta.yxy).x, 
        Dist(pt-delta.yyx).x );
    return normalize( norm );
}

float pow2n(float i,int n)
{
  while ( n-- > 0 ) i *= i;
  return i;
}

void mainImage( out vec4 O, vec2 U )
{

    vec2 R = iResolution.xy;
    vec2 uv = (U+U-R) / min(R.x,R.y);  // -1 ... +1
    uv /= 2.;

    vec3 cam = vec3( 0, 0, -64.);
    vec3 camdir = normalize( vec3( uv, 8. ) );

    //vertsize = sinab(iTime*.02,.3,0.);
    //thick = sinab(iTime*.03,.4,.02);

    vec4 hit = March( cam, camdir );
    vec3 norm = Normal(hit.xyz);

    vec3 light = vec3( 0, 10, -10 );
    vec3 dir = normalize( light - hit.xyz );
    float difu = dot( norm, dir );

    difu = .5 + .5*difu;

    #define col4(X) ( .3 + .6 * cos( vec4(0,21,23,0) + (X) ) )
    O = sqrt( col4(hit.w*1.8) );
    O *= difu + pow2n(difu,9);
    if (hit.w==90.) O=vec4(sin1(fract(hit.y+iTime)*TAU)*.3+.5);
    if (hit.w==91.) O=vec4(fract(hit.x));
}
